class Solution:
    def minMovesToBalance(self, nums: list[int]) -> int:
        n = len(nums)
        target = sum(nums) // n
        diff = [x - target for x in nums]

        pref = [0] * n
        cur = 0
        for i in range(n):
            cur += diff[i]
            pref[i] = cur

        pref.sort()
        med = pref[n // 2]
        return sum(abs(p - med) for p in pref)

