using namespace std;

class Solution {
public:
    int minMovesToBalance(vector<int>& nums) {
        int n = nums.size();
        long long sum = accumulate(nums.begin(), nums.end(), 0LL);
        int target = sum / n;
        vector<long long> pref(n);
        long long cur = 0;
        for (int i = 0; i < n; i++) {
            cur += nums[i] - target;
            pref[i] = cur;
        }
        sort(pref.begin(), pref.end());
        long long med = pref[n / 2];
        long long ans = 0;
        for (long long p : pref) ans += abs(p - med);
        return ans;
    }
};

import java.util.*;

class Solution {
    public int minMovesToBalance(int[] nums) {
        int n = nums.length;
        long sum = 0;
        for (int x : nums) sum += x;
        long target = sum / n;
        long[] pref = new long[n];
        long cur = 0;
        for (int i = 0; i < n; i++) {
            cur += nums[i] - target;
            pref[i] = cur;
        }
        Arrays.sort(pref);
        long med = pref[n / 2];
        long ans = 0;
        for (long p : pref) ans += Math.abs(p - med);
        return (int)ans;
    }
}

var minMovesToBalance = function(nums) {
    const n = nums.length;
    const sum = nums.reduce((a, b) => a + b, 0);
    const target = Math.floor(sum / n);
    const pref = [];
    let cur = 0;
    for (let i = 0; i < n; i++) {
        cur += nums[i] - target;
        pref.push(cur);
    }
    pref.sort((a, b) => a - b);
    const med = pref[Math.floor(n / 2)];
    return pref.reduce((acc, p) => acc + Math.abs(p - med), 0);
};
